/** Fellow-exporter contracts are financial commitments, never warehouse movements. */
function dt_permission(array $u,string $action='View'):bool {
    return tt_user_can_module_action($u,'Directors','exporter-trading',$action);
}
function dt_cost_permission(array $u,string $action='View'):bool {return tt_user_can_module_action($u,'Directors','costing',$action)||dt_permission($u,$action);}
function dt_entity(mixed $v):string {$v=strtoupper(gm_text($v,3));if(!in_array($v,['TTI','BRM'],true))throw new DomainException('Select TTI or BRM company books.');return $v;}
function dt_enum(mixed $v,array $options,string $label):string {$v=gm_text($v,100);if(!in_array($v,$options,true))throw new DomainException('Select '.$label.'.');return $v;}
function dt_positive(mixed $v,string $label):float {$v=gm_number($v,$label);if($v<=0)throw new DomainException($label.' must be positive.');return $v;}
function dt_id(array $rows,string $prefix):string {do{$id=$prefix.'-'.bin2hex(random_bytes(9));}while(isset($rows[$id]));return $id;}
function dt_profiles():array {return json_decode((string)file_get_contents(__DIR__.'/../directors/costing-profiles.json'),true,512,JSON_THROW_ON_ERROR);}
function dt_rules(array $s,string $entity,string $date):?array {
    $best=null;foreach((array)($s['directorCostingRules']??[]) as $r)if($r['entity']===$entity&&$r['effectiveFrom']<=$date&&(!$best||$r['effectiveFrom']>$best['effectiveFrom']))$best=$r;return $best;
}
/** Daily principal integration handles repayments and multiple drawdowns without compounding. */
function dt_finance(array $s,string $entity,array $i):array {
    if(empty($i['enabled']))return ['costPKR'=>0.,'days'=>0,'basis'=>'Financing off'];
    $from=gm_date($i['from']??'');$to=gm_date($i['to']??'');$days=(int)(new DateTimeImmutable($from))->diff(new DateTimeImmutable($to))->format('%r%a');if($days<0||$days>3660)throw new DomainException('Financing end must follow start within ten years.');
    $rate=gm_number($i['annualPct']??null,'annual financing rate')/100;if($rate>1)throw new DomainException('Review the annual financing percentage.');$basis=gm_number($i['dayBasis']??365,'bank day-count basis');if(!in_array($basis,[360.,365.,366.],true))throw new DomainException('Use the bank day-count basis 360, 365 or 366.');
    $fees=gm_number($i['feesPKR']??0,'facility charges');$id=gm_text($i['facilityId']??'',120);$balanceDays=0.;
    if($id!==''){
        $facility=$s['bankFacilities'][$id]??null;if(!$facility||$facility['entity']!==$entity||$facility['currency']!=='PKR')throw new DomainException('Select a PKR finance facility in these books.');
        $moves=[];foreach((array)($s['journals']??[]) as $j){if(($j['entity']??'')!==$entity||($j['status']??'')!=='Posted'||($j['date']??'')>=$to)continue;
            foreach((array)($j['lines']??[]) as $l)if(($l['account']??'')==='2610'&&($l['bankFacilityId']??$j['meta']['bankFacilityId']??'')===$id){$date=gm_date($j['date']);$moves[$date]=($moves[$date]??0)+(float)($l['credit']??0)-(float)($l['debit']??0);}
        }ksort($moves);$balance=0.;foreach($moves as $date=>$move){if($date<=$from)$balance+=$move;}
        for($d=new DateTimeImmutable($from);$d<new DateTimeImmutable($to);$d=$d->modify('+1 day')){$date=$d->format('Y-m-d');if($date>$from)$balance+=$moves[$date]??0;if($balance<-.005)throw new DomainException('Finance principal needs reconciliation.');$balanceDays+=max(0,$balance);}
        $share=gm_number($i['allocationPct']??null,'shipment share of facility financing');if($share>100)throw new DomainException('Facility allocation cannot exceed 100%.');$balanceDays*=$share/100;$label='Posted daily facility principal; shipment share '.$share.'%';
    }else{$balanceDays=gm_number($i['principalPKR']??null,'principal financed')*$days;$label='Entered principal estimate';}
    return ['costPKR'=>round($balanceDays*$rate/$basis+$fees,4),'days'=>$days,'basis'=>$label,'balanceDaysPKR'=>$balanceDays];
}
function dt_cost(array $s,string $entity,array $i):array {
    if(!is_array($i['outputs']??null)||!array_is_list($i['outputs'])||count($i['outputs'])>40)throw new DomainException('Invalid costing output rows.');$date=gm_date($i['date']??'');$fx=dt_positive($i['fx']??null,'USD/PKR rate');$rule=($i['useDatedRule']??true)?dt_rules($s,$entity,$date):null;
    $wht=gm_number($rule['whtPct']??$i['whtPct']??null,'WHT assumption')/100;$bank=gm_number($rule['bankPct']??$i['bankPct']??null,'bank deduction assumption')/100;if($wht+$bank>=1)throw new DomainException('Total deductions must be below 100%.');$netFX=$fx*(1-$wht-$bank);
    $commodity=dt_enum($i['commodity']??'RICE',['RICE','CORN'],'Rice or Maize');$factor=match(dt_enum($i['purchaseUnit']??'KG',['KG','MAUND','MT'],'purchase unit')){'KG'=>1000.,'MAUND'=>25.,'MT'=>1.};
    $raw=gm_number($i['cashPrice']??null,'cash purchase price')*$factor;$credit=isset($i['creditPrice'])&&$i['creditPrice']!==''?gm_number($i['creditPrice'],'udhaar purchase price')*$factor:null;
    $mill=gm_number($i['millingPKRPerKg']??0,'milling charge')*1000;if($commodity==='CORN'&&$mill>0)throw new DomainException('Maize has no rice milling charge.');$sum=0.;$recovery=0.;$byvalue=0.;$names=[];
    foreach((array)($i['outputs']??[]) as $r){$name=gm_text($r['product']??'',80);if($name===''||isset($names[strtoupper($name)]))throw new DomainException('Use unique output names.');$names[strtoupper($name)]=true;$yield=gm_number($r['recoveryPct']??null,'output recovery');$sum+=$yield;$kind=dt_enum($r['kind']??'',['finished','byproduct','waste'],'output kind');
        if($kind==='finished')$recovery+=$yield/100;elseif($kind==='byproduct'&&$yield>0){if($commodity==='CORN')throw new DomainException('Direct-loading maize has no milling by-products.');$byvalue+=10*$yield*gm_number($r['ratePKRPerKg']??null,$name.' price');}elseif($kind==='waste'&&(float)($r['ratePKRPerKg']??0)!==0.)throw new DomainException('Loss has no sale value.');
    }if(abs($sum-100)>.00001||$recovery<=0)throw new DomainException('Finished output, by-products and loss must total 100%.');
    $basis=dt_enum($i['incoterm']??'FOB',['FOB','CNF','CIF'],'shipment basis');$qty=dt_positive($i['quantityMT']??null,'finished quantity');$otherPKR=gm_number($i['otherFOBPKRPerMT']??0,'other FOB in PKR');$otherUSD=gm_number($i['otherFOBUSDPerMT']??0,'other FOB in USD');
    $packing=gm_number($i['packingAdjustment']??null,'packing adjustment',true);$packingCurrency=dt_enum($i['packingCurrency']??'USD',['USD','PKR'],'packing currency');if($packingCurrency==='PKR')$otherPKR+=$packing;else$otherUSD+=$packing;
    $thc=gm_number($i['thcUSDPerMT']??0,'THC');$freight=$basis==='FOB'?0:gm_number($i['freightUSDPerContainer']??null,'freight per container')/dt_positive($i['payloadMT']??null,'container payload');$insurance=$basis==='CIF'?gm_number($i['insuranceUSDPerMT']??null,'insurance'):0;
    $finance=dt_finance($s,$entity,(array)($i['finance']??[]));$out=[];
    foreach(['cash'=>$raw,'udhaar'=>$credit,'financedCash'=>$raw] as $k=>$purchase){if($purchase===null){$out[$k]=null;continue;}$material=($purchase+$mill-$byvalue)/$recovery;if($material<0)throw new DomainException('By-product credit exceeds purchase and milling cost.');$funding=$k==='financedCash'?$finance['costPKR']/$qty:0;$cost=($material+$otherPKR+$funding)/$netFX+$otherUSD+$thc+$freight+$insurance;if($cost<0)throw new DomainException('Review the packing adjustment.');$out[$k]=['materialPKRPerMT'=>round($material,4),'financingPKRPerMT'=>round($funding,4),'costUSDPerMT'=>round($cost,4),'costPKRPerMT'=>round($cost*$fx,4),'shipmentUSD'=>round($cost*$qty,2)];}
    return ['date'=>$date,'effectiveFX'=>$netFX,'finishedRecoveryPct'=>$recovery*100,'byproductCreditPKRPerInputMT'=>$byvalue,'finance'=>$finance,'costs'=>$out,'ruleId'=>$rule['id']??'Entered assumptions','basis'=>'Cost only; entered rates and dated rule snapshot. No accounting posting.'];
}
function dt_lots(array $root,string $entity):array {
    $out=[];$contracts=array_column((array)($root['contracts']??[]),null,'ref');
    foreach(tt_accounts_shipment_rows($root,$entity) as $row){$sh=null;foreach((array)($root['shipments']??[]) as $r)if(($r['id']??'')===$row['id'])$sh=$r;if(!$sh)continue;$c=$contracts[$row['contract']]??[];$mt=0.;foreach((array)($sh['millActuals']??[]) as $a)$mt+=(float)($a['millNetKg']??$a['netKg']??0)/1000;
        $invoice=(string)($sh['commercial']['invoiceNo']??'');$packs=(array)($c['packings']??[]);$rates=[];foreach($packs as $p){$inc=strtoupper((string)($c['incoterm']??'FOB'));$rates[]=((float)($p['contractRate']??0))?:((float)($p['price']??0)+($inc==='FOB'?0:(float)($p['freight']??0))+($inc==='CIF'?(float)($p['insurance']??0):0));}$rates=array_values(array_unique($rates));
        $out[$row['id']]=$row+['invoice'=>$invoice,'invoiceDate'=>$sh['commercial']['date']??'','quantityMT'=>round($mt,6),'contractPrice'=>count($rates)===1?$rates[0]:null,'currency'=>$c['currency']??'USD','incoterm'=>$c['incoterm']??'','commodity'=>$c['commodity']??'RICE','product'=>$c['product']??'','invoiceSaved'=>!empty($sh['commercial']['saved'])];
    }return $out;
}
function dt_deal(array $b,array $parties):array {
    $partyId=gm_text($b['partyId']??'',120);$party=null;foreach($parties as $r)if((string)$r['id']===$partyId)$party=$r;if(!$party)throw new DomainException('Select an active fellow exporter from Business Parties.');
    $d=['entity'=>dt_entity($b['entity']??''),'date'=>gm_date($b['date']??''),'direction'=>dt_enum($b['direction']??'',['PURCHASE','SALE'],'purchase from or sale through exporter'),'arrangement'=>dt_enum($b['arrangement']??'',['FIXED','SETTLEMENT'],'fixed price or quantity settlement'),'partyId'=>$partyId,'party'=>$party['name'],'currency'=>dt_enum($b['currency']??'USD',['USD','PKR'],'USD or PKR'),'price'=>dt_positive($b['price']??null,'agreed price per MT'),'quantityMT'=>dt_positive($b['quantityMT']??null,'contract quantity MT'),'incoterm'=>dt_enum($b['incoterm']??'',['FOB','CNF','CIF'],'FOB, CNF or CIF')];
