}
function dt_parties():array {$out=[];foreach((array)(tt_list_masters()['business_parties']??[]) as $r){$v=(array)($r['values']??[]);if(strcasecmp((string)($v[10]??'Active'),'Inactive')!==0&&trim((string)($v[0]??''))!=='')$out[]=['id'=>(string)$r['id'],'name'=>(string)$v[0]];}return $out;}
/** Posted shipment bills replace estimates component by component. No cash payments are re-expensed. */
function dt_expenses(array $s,array $lot,string $date):array {
    $out=[];foreach((array)($s['supplierBills']??[]) as $id=>$bill){if(($bill['entity']??'')!==$lot['pakistanExporter']||($bill['billDate']??'')>$date||in_array($bill['status']??'',['Cancelled','Reversed'],true))continue;$src=(array)($bill['sourceRecord']??[]);$amount=null;
        foreach((array)($src['shipmentSections']??[]) as $section)if(($section['shipmentId']??'')===$lot['id'])$amount=($amount??0)+(float)$section['amount'];
        if($amount===null&&($src['shipmentId']??'')===$lot['id']&&count((array)($src['shipmentIds']??[]))<=1)$amount=(float)($bill['supplierPayableTotal']??0);
        if($amount!==null)$out[]=['id'=>(string)$id,'category'=>(string)($bill['category']??'OTHER'),'description'=>($bill['vendor']??'').' / '.($bill['billNo']??''),'amountPKR'=>$amount,'date'=>$bill['billDate'],'journalIds'=>$bill['postingJournalIds']??[]];
    }
    $sources=dt_expense_sources($s,$lot['pakistanExporter'],$date);foreach((array)($s['exporterExpenseAllocations']??[]) as $a){if(!($a['active']??true)||$a['entity']!==$lot['pakistanExporter']||$a['shipmentId']!==$lot['id']||$a['date']>$date)continue;$source=$sources[$a['sourceId']]??null;$valid=$source&&$source['unallocatedPKR']>=-.005;$out[]=['id'=>$a['id'],'category'=>$a['category'],'description'=>$a['description'],'amountPKR'=>$valid?$a['amountPKR']:0.,'date'=>$a['date'],'journalIds'=>[$a['postId']],'invalidAllocation'=>!$valid];}
    return $out;
}
function dt_advice(array $s,array $lot,string $date):array {
    $out=[];foreach((array)($s['exportReceipts']??[]) as $r){if(($r['entity']??'')!==$lot['pakistanExporter']||($r['date']??'')>$date||!in_array($r['status']??'',['Posted','Accounts Approved / Posted'],true)||!empty($r['replacementReceiptId'])||!empty($r['amendedByReceiptId'])||!empty($r['reversedByPostId']))continue;$all=0.;$matched=0.;$invoiceFraction=0.;
        foreach((array)($r['allocations']??[]) as $a){$n=(float)($a['foreignAmount']??0);$all+=$n;$candidate=$s['exportCandidates'][$a['targetId']??'']??[];$m=(array)($candidate['meta']??$a);if(($m['contractRef']??'')===$lot['contract']&&in_array($m['lotRef']??'',[$lot['id'],$lot['lot']],true)){$matched+=$n;$invoiceFraction+=(float)($candidate['transactionAmount']??0)>0?$n/(float)$candidate['transactionAmount']:0;}}
        if($matched<=0||$all<=0)continue;$ded=(float)($r['correspondentPkrAmount']??0);foreach((array)($r['deductions']??[]) as $d)$ded+=(float)($d['amount']??0);$out[]=['id'=>$r['id'],'date'=>$r['date'],'reference'=>$r['bankAdviceRef']??'','amountPKR'=>round($ded*$matched/$all,4),'invoiceAllocation'=>$matched/$all,'invoiceFraction'=>$invoiceFraction,'realizationRate'=>dt_positive($r['realizationRate']??null,'original credit advice exchange rate')];
    }return $out;
