        $components=[];foreach($actual as $a)$components[$a['category']]=($components[$a['category']]??0)+$a['amountPKR'];
        $estimate=$d['fobEstimateUSDPerMT']*$load['totalInvoiceMT']*$d['fx'];$fob=0.;foreach($components as $kind=>$amount)if(!in_array($kind,['FREIGHT','INSURANCE','BANK'],true))$fob+=$amount;
        $invalid=count(array_filter($actual,static fn($a)=>!empty($a['invalidAllocation'])))>0;if($invalid)$warnings[]=$load['invoiceRef'].': a linked expense was amended or reversed; reconcile its allocation.';$actualReviewed=!$invalid&&!empty($load['expensesComplete'])&&isset($load['reviewHash'])&&hash_equals($load['reviewHash'],dt_source_hash($s,$load,$lots,$date));$fobTotal=$actualReviewed?$fob:max($fob,$estimate);$freightTotal=$d['incoterm']==='FOB'?0:($components['FREIGHT']??($actualReviewed?0:($d['freightEstimateUSDPerMT']*$load['totalInvoiceMT']*$d['fx'])));$insurance=$d['incoterm']==='CIF'?($components['INSURANCE']??($actualReviewed?0:($d['insuranceEstimateUSDPerMT']*$load['totalInvoiceMT']*$d['fx']))):0;
        $deduction=array_sum(array_column($advice,'amountPKR'))+($components['BANK']??0);$fraction=min(1.,array_sum(array_column($advice,'invoiceFraction')));$effectiveFX=$d['fx']*(1-$fraction);foreach($advice as $a)$effectiveFX+=$a['realizationRate']*$a['invoiceFraction'];if($fraction>=1&&array_sum(array_column($advice,'invoiceFraction'))>1.000001)throw new DomainException('Credit advice allocations exceed the invoice; reconcile the source receipts.');$adjustments=0.;foreach((array)($load['adjustments']??[]) as $a)$adjustments+=$a['amountPKR'];
        if($d['arrangement']==='FIXED'){$gross=$qty*$d['price']*($d['currency']==='USD'?$d['fx']:1);$costs=$d['direction']==='SALE'?($fobTotal+$freightTotal+$insurance+$deduction)*$share:($freightTotal+$insurance)*$share;$amount=$gross-$costs-$adjustments;}
