        if($amount<0)$warnings[]='Negative settlement on '.$load['invoiceRef'].' requires review.';if($fob>$estimate+.005)$warnings[]=$load['invoiceRef'].': actual FOB expenses exceed the saved allowance.';if(!$actualReviewed&&$d['arrangement']==='SETTLEMENT')$warnings[]=$load['invoiceRef'].': expense completeness still requires review.';
        $rows[]=['loadingId'=>$load['id'],'invoice'=>$load['invoiceRef'],'quantityMT'=>$qty,'invoiceQuantityMT'=>$load['totalInvoiceMT'],'sharePct'=>round($share*100,6),'grossPKR'=>round($gross,2),'expensesPKR'=>round($costs,2),'adjustmentsPKR'=>round($adjustments,2),'settlementPKR'=>round($amount,2),'actualFOBUSDPerMT'=>$load['totalInvoiceMT']>0?round($fob/$load['totalInvoiceMT']/$d['fx'],4):null,'actualBills'=>$actual,'creditAdvices'=>$advice,'expensesComplete'=>$actualReviewed,'creditAdviceCoveragePct'=>$fraction*100,'settlementFX'=>$effectiveFX];$total+=$amount;
    }
