        $total=$lot['quantityMT'];if($total<=0)throw new DomainException('Save actual invoice loading weights in Exports first.');$external=0.;foreach((array)($s['exporterDeals']??[]) as $other)foreach((array)($other['loadings']??[]) as $l)if(($l['shipmentId']??'')===$lot['id'])$external+=$l['quantityMT'];if($external+$qty>$total+.000001)throw new DomainException('Fellow-exporter allocations exceed the commercial invoice quantity.');
        // Existing posted inventory cost must be reconciled before classifying external goods.
