        if(mr_valid_date((string)$lot['invoiceDate'])&&$date<$lot['invoiceDate'])throw new DomainException('Contribution date must not precede the saved invoice date.');$invoice=$lot['invoice'];$sid=$lot['id'];$price=$lot['contractPrice'];$currency=$lot['currency'];if($d['arrangement']==='SETTLEMENT'&&($price===null||$price<=0))throw new DomainException('This invoice has several contract prices. Split by packing in Exports before settlement.');
    }else{$total=dt_positive($b['totalInvoiceMT']??null,'fellow exporter commercial invoice total MT');$invoice=gm_text($b['invoiceRef']??'',160);$sid='EXTERNAL|'.$d['entity'].'|'.$d['partyId'].'|'.hash('sha256',strtoupper($invoice));$price=dt_positive($b['contractPrice']??$d['price'],'end-buyer contract price');$currency=dt_enum($b['contractCurrency']??$d['currency'],['USD','PKR'],'contract currency');if($invoice==='')throw new DomainException('Enter the fellow exporter invoice reference.');if($qty>$total)throw new DomainException('Loaded tonnes exceed invoice tonnes.');$used=0.;foreach((array)($s['exporterDeals']??[]) as $other)foreach((array)($other['loadings']??[]) as $l)if(($l['shipmentId']??'')===$sid){if(abs($l['totalInvoiceMT']-$total)>.000001)throw new DomainException('Use the original total MT for this fellow-exporter invoice.');$used+=$l['quantityMT'];}if($used+$qty>$total+.000001)throw new DomainException('Contributions already recorded against this invoice exceed its total MT.');}
    if($date>$b['asOf'])throw new DomainException('Loading cannot be future dated.');$adjust=[];foreach((array)($b['adjustments']??[]) as $a){$reason=gm_text($a['reason']??'',500);if($reason==='')throw new DomainException('Each exporter-attributable adjustment needs a reason.');$adjust[]=['reason'=>$reason,'amountPKR'=>gm_number($a['amountPKR']??null,'agreed exporter adjustment',true)];}
    return ['id'=>dt_id([],'LOAD'),'date'=>$date,'shipmentId'=>$sid,'invoiceRef'=>$invoice,'quantityMT'=>$qty,'totalInvoiceMT'=>$total,'contractPrice'=>$price??$d['price'],'contractCurrency'=>$currency,'expensesComplete'=>false,'adjustments'=>$adjust,'sourceSnapshot'=>$lot,'stockEffect'=>'NONE_EXTERNAL'];
}
/** Journal balance is the single remaining-balance authority after posting/payment. */
function dt_book_balance(array $s,string $id,string $date):float {$v=0.;foreach((array)($s['journals']??[]) as $j)if(($j['status']??'')==='Posted'&&($j['date']??'')<=$date)foreach((array)($j['lines']??[]) as $l)if(($l['exporterDealId']??'')===$id&&in_array($l['account']??'',['1230','2140'],true))$v+=(float)($l['debit']??0)-(float)($l['credit']??0);return round($v,2);}
function dt_cashflow(array $s,array $lots,string $entity,string $date):array {
    $out=[];foreach((array)($s['exporterDeals']??[]) as $d){if($d['entity']!==$entity||$d['date']>$date)continue;$w=dt_working($s,$d,$lots,$date);$book=dt_book_balance($s,$d['id'],$date);$firm=0.;foreach((array)($d['settlementPosts']??[]) as $p)if($p['date']<=$date&&empty($s['journals'][$p['postId']]['reversedByPostId'])&&($s['journals'][$p['postId']]['status']??'')==='Posted')$firm+=$p['amountPKR'];$sign=$d['direction']==='PURCHASE'?-1:1;$unposted=($w['settlementPKR']-$firm+$w['unloadedForecastPKR'])*$sign;
        $out[]=['id'=>$d['id'],'party'=>$d['party'],'direction'=>$w['direction'],'bookBalancePKR'=>$book,'forecastOnlyPKR'=>round($unposted,2),'totalExpectedPKR'=>round($book+$unposted,2),'warnings'=>$w['warnings'],'basis'=>'Posted balance already belongs to group books. Only forecastOnlyPKR is additional.'];
    }return $out;
}
function dt_coverage(array $s,string $contract,string $date):float {$qty=0.;foreach((array)($s['exporterDeals']??[]) as $d)if($d['direction']==='PURCHASE'&&$d['contractRef']===$contract&&$d['date']<=$date){$loaded=0.;foreach((array)($d['loadings']??[]) as $l)if($l['date']<=$date)$loaded+=$l['quantityMT'];$qty+=max(0,$d['coverageMT']-$loaded);}return $qty;}
/** Externally supplied goods never consume our inventory value in Export COGS. */
function dt_external_mt(array $s,array $candidate):float {$qty=0.;foreach((array)($s['exporterDeals']??[]) as $d)if($d['direction']==='PURCHASE'&&$d['entity']===($candidate['entity']??''))foreach((array)($d['loadings']??[]) as $l)if(($l['sourceSnapshot']['contract']??'')===($candidate['meta']['contractRef']??'')&&in_array($candidate['meta']['lotRef']??'',[$l['shipmentId'],$l['sourceSnapshot']['lot']??''],true))$qty+=$l['quantityMT'];return $qty;}
function dt_source_hash(array $s,array $load,array $lots,string $date):string {$lot=$lots[$load['shipmentId']]??null;return hash('sha256',json_encode([$lot,$lot?dt_expenses($s,$lot,$date):($load['externalExpenses']??[]),$lot?dt_advice($s,$lot,$date):[]],JSON_THROW_ON_ERROR));}
function dt_post_settlement(array &$s,array &$d,array $w,array $u,string $date):array {
    if(!$w['rows'])throw new DomainException('Record actual invoice loading before posting settlement.');
    foreach($w['rows'] as $r){if($d['direction']==='PURCHASE'&&$d['arrangement']==='SETTLEMENT'&&$r['creditAdviceCoveragePct']<99.9999)throw new DomainException('Full invoice credit advice is still pending. The estimated settlement remains in cash flow.');}foreach($w['rows'] as $r)if(!$r['expensesComplete']&&$d['arrangement']==='SETTLEMENT')throw new DomainException('Review complete expenses and credit advice for every loaded invoice first.');
    $previous=0.;foreach((array)($d['settlementPosts']??[]) as $p){$j=$s['journals'][$p['postId']]??[];if(empty($j['reversedByPostId'])&&($j['status']??'')==='Posted')$previous+=$p['amountPKR'];}$delta=round($w['settlementPKR']-$previous,2);if(abs($delta)<.005)throw new DomainException('This settlement is already posted with the current figures.');if($w['settlementPKR']<0)throw new DomainException('A negative settlement requires an explicit reviewed amendment.');
    $purchase=$d['direction']==='PURCHASE';$amount=(int)round(abs($delta)*100);$positive=$delta>0;$meta=['exporterDealId'=>$d['id'],'counterparty'=>$d['party'],'partyId'=>$d['partyId'],'contractRef'=>$d['contractRef'],'settlementCurrency'=>$d['currency'],'stockEffect'=>'NONE_EXTERNAL'];
    $control=$purchase?'2140':'1230';$opposite=$purchase?'5100':'4100';$debitControl=$purchase?!$positive:$positive;
    $lines=[ben_line($control,$debitControl?$amount:0,$debitControl?0:$amount,$meta),ben_line($opposite,$debitControl?0:$amount,$debitControl?$amount:0,$meta)];
    $j=ben_journal($s,$d['entity'],$date,$d['reference']?:$d['id'],'Exporter settlement — '.$d['party'],$lines,$u,$meta);$s['journals'][$j['id']]['sourceType']='FELLOW_EXPORTER_SETTLEMENT';$d['settlementPosts'][]=['postId'=>$j['id'],'date'=>$date,'amountPKR'=>$delta,'working'=>$w];return ['postId'=>$j['id'],'amountPKR'=>$delta];
}
function dt_payment(array &$s,array &$d,array $b,array $u,string $date):array {
    $balance=dt_book_balance($s,$d['id'],$date);$amount=dt_positive($b['amountPKR']??null,'settlement amount PKR');if($amount>abs($balance)+.005)throw new DomainException('Payment exceeds the posted outstanding balance. Post/review the settlement first.');
    $incoming=$balance>0;$id=gm_text($b['bankId']??'',120);$bank=$id==='CASH|'.$d['entity']?['id'=>$id,'currency'=>'PKR','kind'=>'CASH']:ben_bank($s,$d['entity'],$id);if($bank['currency']!=='PKR')throw new DomainException('Choose PKR cash/bank for this PKR settlement; foreign-bank conversion uses Accounts.');
    $ref=gm_text($b['reference']??'',180);if($ref==='')throw new DomainException('Enter the payment/receipt reference.');$tracking=($bank['kind']??'')==='CASH'?[]:ben_tracking($s,$d['entity'],$bank,$b+['bankPaymentMethod'=>'ONLINE_BANKING']);$cents=(int)round($amount*100);$meta=['exporterDealId'=>$d['id'],'counterparty'=>$d['party'],'partyId'=>$d['partyId'],'stockEffect'=>'NONE_EXTERNAL'];
    $lines=[ben_line($incoming?'1230':'2140',$incoming?0:$cents,$incoming?$cents:0,$meta),ben_bank_line($bank,$cents,1,$incoming,$tracking+$meta)];$j=ben_journal($s,$d['entity'],$date,$ref,($incoming?'Receipt from ':'Payment to ').$d['party'],$lines,$u,$meta+$tracking);$s['journals'][$j['id']]['sourceType']='FELLOW_EXPORTER_PAYMENT';$d['payments'][]=['postId'=>$j['id'],'date'=>$date,'amountPKR'=>$amount,'incoming'=>$incoming];return ['postId'=>$j['id']];
}
/** Costing market inputs are dated estimates; they never replace approved inventory cost. */
function dt_market_prices(array $s,string $date):array {
    $rows=(array)($s['directorCostings']??[]);usort($rows,static fn($a,$b)=>strcmp($a['date'],$b['date'])?:strcmp($a['savedAt']??'',$b['savedAt']??''));$out=[];
    foreach($rows as $r){if($r['date']>$date)continue;$i=$r['input'];$entity=$r['entity'];$add=static function(string $product,mixed $rate)use(&$out,$r,$entity):void {if($product===''||$rate===null||$rate===''||!is_numeric($rate))return;$out[$entity.'|'.strtoupper(trim($product))]=['product'=>$product,'ratePKRPerKg'=>(float)$rate,'date'=>$r['date'],'costingId'=>$r['id']];};
        foreach((array)($i['outputs']??[]) as $o)if(($o['kind']??'')==='byproduct')$add((string)$o['product'],$o['ratePKRPerKg']??null);
        $kg=match($i['purchaseUnit']??'KG'){'MAUND'=>40.,'MT'=>1000.,default=>1.};$add((string)($i['marketRawProduct']??''),isset($i['cashPrice'])?(float)$i['cashPrice']/$kg:null);$add((string)($i['marketFinishedProduct']??''),$i['marketFinishedPKRPerKg']??null);
    }return $out;
}
function dt_stock_valuation(array $stocks,array $financials,array $books,string $date):array {
    $prices=dt_market_prices($books,$date);$rows=[];$missing=[];$total=0.;foreach($stocks as $stock){$qty=(float)$stock['quantityMT'];if(abs($qty)<.000001)continue;$key=$stock['entity'].'|'.strtoupper(trim((string)$stock['product']));$rate=$prices[$key]??null;
        if(!$rate||empty($stock['known'])||$qty<0){$missing[]=$stock['entity'].' / '.$stock['product'];$value=null;}else{$value=round($qty*1000*$rate['ratePKRPerKg'],2);$total+=$value;}$rows[]=['stockId'=>$stock['id'],'entity'=>$stock['entity'],'product'=>$stock['product'],'quantityMT'=>$qty,'ratePKRPerKg'=>$rate['ratePKRPerKg']??null,'valuePKR'=>$value,'rateDate'=>$rate['date']??'','costingId'=>$rate['costingId']??''];
    }
    $book=0.;foreach($financials as $row)if(in_array($row['entity']??'',['TTI','BRM'],true)&&in_array($row['account']??'',['1310','1320','1330'],true)&&empty($row['excluded']))$book+=(float)$row['amount'];$complete=!$missing&&count($rows)>0;
    return ['rows'=>$rows,'unpriced'=>$missing,'complete'=>$complete,'marketValuePKR'=>round($total,2),'bookInventoryPKR'=>round($book,2),'valuationAdjustmentPKR'=>$complete?round($total-$book,2):null,'basis'=>'Exact stock product names matched to dated costing market inputs. Replaces the corresponding TTI/BRM commodity inventory book value only when all positive known quantities are priced. External fellow-exporter goods are excluded.'];
}
/** Explicit shared-bill allocations cover bags/other expenses without re-posting invoices. */
function dt_expense_sources(array $s,string $entity,string $date):array {
    $out=[];$auto=[];foreach((array)($s['supplierBills']??[]) as $bill)foreach((array)($bill['postingJournalIds']??[]) as $id)$auto[$id]=true;
    foreach((array)($s['bagSupplierBills']??[]) as $id=>$b){$j=$s['journals'][$b['journalId']??'']??null;if(($b['entity']??'')!==$entity||($b['status']??'')!=='Posted'||($b['sellerInvoiceDate']??'')>$date||!$j||($j['status']??'')!=='Posted'||!empty($j['reversedByPostId']))continue;$key='BAG|'.$id;$out[$key]=['id'=>$key,'date'=>$b['sellerInvoiceDate'],'description'=>($b['supplier']??'').' / Bags '.$b['sellerInvoice'],'amountPKR'=>(float)$b['baseAmount'],'category'=>'BAGS','postId'=>$b['journalId']];$auto[$b['journalId']]=true;}
    foreach((array)($s['journals']??[]) as $id=>$j){if(isset($auto[$id])||($j['entity']??'')!==$entity||($j['status']??'')!=='Posted'||($j['date']??'')>$date||!empty($j['reversedByPostId'])||!empty($j['reversalOf']))continue;$amount=0.;foreach((array)($j['lines']??[]) as $l)if(in_array($l['account']??'',['5300','5550','5510','5520','5530','5540','5560','6700'],true))$amount+=(float)($l['debit']??0)-(float)($l['credit']??0);if($amount<=0)continue;$key='POST|'.$id;$out[$key]=['id'=>$key,'date'=>$j['date'],'description'=>$id.' / '.($j['narration']??$j['reference']??''),'amountPKR'=>$amount,'category'=>'OTHER','postId'=>$id];}
    foreach($out as $key=>&$r){$used=0.;foreach((array)($s['exporterExpenseAllocations']??[]) as $a)if(($a['active']??true)&&$a['sourceId']===$key)$used+=$a['amountPKR'];$r['unallocatedPKR']=round($r['amountPKR']-$used,2);}unset($r);return $out;
}
function dt_allocate_expense(array &$s,array $d,array $b,array $lots,string $date):array {
    $load=null;foreach($d['loadings'] as $l)if($l['id']===($b['loadingId']??''))$load=$l;if(!$load||!isset($lots[$load['shipmentId']]))throw new DomainException('Choose an original company shipment loading.');$sources=dt_expense_sources($s,$d['entity'],$date);$source=$sources[$b['sourceId']??'']??null;if(!$source)throw new DomainException('Choose a posted expense or bag invoice in these books.');$amount=dt_positive($b['amountPKR']??null,'expense share for this invoice');if($amount>$source['unallocatedPKR']+.005)throw new DomainException('Allocation exceeds the unallocated original expense.');$id=dt_id((array)($s['exporterExpenseAllocations']??[]),'ALC');$s['exporterExpenseAllocations'][$id]=['id'=>$id,'entity'=>$d['entity'],'shipmentId'=>$load['shipmentId'],'sourceId'=>$source['id'],'amountPKR'=>$amount,'category'=>dt_enum($b['category']??$source['category'],['BAGS','FOB','FREIGHT','INSURANCE','OTHER'],'charge type'),'description'=>$source['description'],'postId'=>$source['postId'],'date'=>$date,'active'=>true];return ['allocationId'=>$id];
}
